1	// =============================================================================
2	// Entry point — CSS Cascade Layers ordering.
3	//
4	// Load order:
5	//   1. Font @imports (MUST be at stylesheet root — CSS spec forbids @import
6	//      nested inside @layer blocks; violation silently drops the rules and
7	//      breaks web fonts like Clash Display / --fm-en).
8	//   2. @layer declaration — fixes priority independent of source order.
9	//   3. Layer blocks populated via meta.load-css so each partial stays
10	//      independently editable and source maps resolve to the original file.
11	//
12	// Layer priority (low → high):
13	//   reset < base < layout < components < pages < utilities < state
14	//
15	// Rationale:
16	//   - `pages` sits above `components` so page-specific overrides win without
17	//     specificity games.
18	//   - `utilities` above `pages` so `.f-display-0`, `.--regular`, `.--fm-en`
19	//     etc. always trump page/component rules — mirrors the old @use source
20	//     order where base/ loaded before components/ and utils were always last.
21	//   - `_root.scss` (CSS custom properties + typography/color/container utility
22	//     classes) lives in `utilities` so .f-*/.clr-* classes win over components
23	//     and pages. :root{} custom properties work correctly in any layer.
24	//   - `state` is the highest — TS-driven `data-reveal`, `data-mask`, `is-*`
25	//     dynamic state always wins, without !important.
26	// =============================================================================
27	
28	@use "sass:meta";
29	
30	// --- Fonts first (root-level @import) ---
31	@include meta.load-css("base/fonts");
32	
33	@layer reset, base, layout, components, pages, utilities, state;
34	
35	@layer reset {
36	  @include meta.load-css("base/reset");
37	}
38	
39	@layer base {
40	  @include meta.load-css("base/init");
41	}
42	
43	@layer layout {
44	  @include meta.load-css("layouts/header");
45	  @include meta.load-css("layouts/drawer");
46	  @include meta.load-css("layouts/footer");
47	}
48	
49	@layer components {
50	  @include meta.load-css("components/backdrop");
51	  @include meta.load-css("components/masking-text");
52	  @include meta.load-css("components/corner-bracket");
53	  @include meta.load-css("components/button");
54	  @include meta.load-css("components/dropdown");
55	  @include meta.load-css("components/intro");
56	  @include meta.load-css("components/form");
57	  @include meta.load-css("components/marquee");
58	  @include meta.load-css("components/search-bar");
59	  @include meta.load-css("components/modal");
60	  @include meta.load-css("components/pagination");
61	  @include meta.load-css("components/prevnext");
62	  @include meta.load-css("components/table");
63	  @include meta.load-css("components/hud-panel");
64	  @include meta.load-css("components/panel");
65	  @include meta.load-css("components/hud");
66	  @include meta.load-css("components/meta");
67	  @include meta.load-css("components/category");
68	  @include meta.load-css("components/toast");
69	  @include meta.load-css("components/loading");
70	  @include meta.load-css("components/loop-filter-rect");
71	  @include meta.load-css("components/custom-cursor");
72	  @include meta.load-css("components/space-card");
73	}
74	
75	@layer pages {
76	  @include meta.load-css("pages/main");
77	  @include meta.load-css("pages/sub");
78	  @include meta.load-css("pages/works-canvas");
79	}
80	
81	@layer utilities {
82	  @include meta.load-css("base/root");
83	  @include meta.load-css("base/utils");
84	}
85	
86	@layer state {
87	  @include meta.load-css("state/reveal-state");
88	}
