1	@use "../abstract" as *;
2	
3	/*
4	CSS @property and the New Style
5	https://ryanmulligan.dev/blog/css-property-new-style/
6	*/
7	@property --gradient-angle {
8	  syntax: "<angle>";
9	  initial-value: 0deg;
10	  inherits: false;
11	}
12	
13	@property --gradient-angle-offset {
14	  syntax: "<angle>";
15	  initial-value: 0deg;
16	  inherits: false;
17	}
18	
19	@property --gradient-percent {
20	  syntax: "<percentage>";
21	  initial-value: 5%;
22	  inherits: false;
23	}
24	
25	@property --gradient-shine {
26	  syntax: "<color>";
27	  initial-value: white;
28	  inherits: false;
29	}
30	
31	.shiny-cta {
32	  --animation: gradient-angle linear infinite;
33	  --duration: 3s;
34	  --shadow-size: 2px;
35	  isolation: isolate;
36	  position: relative;
37	  overflow: hidden;
38	  cursor: pointer;
39	  outline-offset: 4px;
40	  padding: 1.25rem 2.5rem;
41	  font-family: inherit;
42	  font-size: 1.125rem;
43	  line-height: 1.2;
44	  border: 1px solid transparent;
45	  border-radius: 360px;
46	  color: var(--shiny-cta-fg);
47	  background:
48	    linear-gradient(var(--shiny-cta-bg), var(--shiny-cta-bg)) padding-box,
49	    conic-gradient(
50	        from calc(var(--gradient-angle) - var(--gradient-angle-offset)),
51	        transparent,
52	        var(--shiny-cta-highlight) var(--gradient-percent),
53	        var(--gradient-shine) calc(var(--gradient-percent) * 2),
54	        var(--shiny-cta-highlight) calc(var(--gradient-percent) * 3),
55	        transparent calc(var(--gradient-percent) * 4)
56	      )
57	      border-box;
58	  box-shadow: inset 0 0 0 1px var(--shiny-cta-bg-subtle);
59	
60	  &::before,
61	  &::after,
62	  span::before {
63	    content: "";
64	    pointer-events: none;
65	    position: absolute;
66	    inset-inline-start: 50%;
67	    inset-block-start: 50%;
68	    translate: -50% -50%;
69	    z-index: -1;
70	  }
71	
72	  &:active {
73	    translate: 0 1px;
74	  }
75	}
76	
77	/* Dots pattern */
78	.shiny-cta::before {
79	  --size: calc(100% - var(--shadow-size) * 3);
80	  --position: 2px;
81	  --space: calc(var(--position) * 2);
82	  width: var(--size);
83	  height: var(--size);
84	  background: radial-gradient(
85	      circle at var(--position) var(--position),
86	      white calc(var(--position) / 4),
87	      transparent 0
88	    )
89	    padding-box;
90	  background-size: var(--space) var(--space);
91	  background-repeat: space;
92	  mask-image: conic-gradient(
93	    from calc(var(--gradient-angle) + 45deg),
94	    black,
95	    transparent 10% 90%,
96	    black
97	  );
98	  border-radius: inherit;
99	  opacity: 0.4;
100	  z-index: -1;
101	}
102	
103	/* Inner shimmer */
104	.shiny-cta::after {
105	  --animation: shimmer linear infinite;
106	  width: 100%;
107	  aspect-ratio: 1;
108	  background: linear-gradient(
109	    -50deg,
110	    transparent,
111	    var(--shiny-cta-highlight),
112	    transparent
113	  );
114	  mask-image: radial-gradient(circle at bottom, transparent 40%, black);
115	  opacity: 0.6;
116	}
117	
118	.shiny-cta span {
119	  z-index: 1;
120	
121	  &::before {
122	    --size: calc(100% + 1rem);
123	    width: var(--size);
124	    height: var(--size);
125	    box-shadow: inset 0 -1ex 2rem 4px var(--shiny-cta-highlight);
126	    opacity: 0;
127	  }
128	}
129	
130	/* Animate */
131	.shiny-cta {
132	  --transition: 800ms cubic-bezier(0.25, 1, 0.5, 1);
133	  transition: var(--transition);
134	  transition-property:
135	    --gradient-angle-offset, --gradient-percent, --gradient-shine;
136	
137	  &,
138	  &::before,
139	  &::after {
140	    animation:
141	      var(--animation) var(--duration),
142	      var(--animation) calc(var(--duration) / 0.4) reverse paused;
143	    animation-composition: add;
144	  }
145	
146	  span::before {
147	    transition: opacity var(--transition);
148	    animation: calc(var(--duration) * 1.5) breathe linear infinite;
149	  }
150	}
151	
152	.shiny-cta:is(:hover, :focus-visible) {
153	  --gradient-percent: 20%;
154	  --gradient-angle-offset: 95deg;
155	  --gradient-shine: var(--shiny-cta-highlight-subtle);
156	
157	  &,
158	  &::before,
159	  &::after {
160	    animation-play-state: running;
161	  }
162	
163	  span::before {
164	    opacity: 1;
165	  }
166	}
167	
168	@keyframes gradient-angle {
169	  to {
170	    --gradient-angle: 360deg;
171	  }
172	}
173	
174	@keyframes shimmer {
175	  to {
176	    rotate: 360deg;
177	  }
178	}
179	
180	@keyframes breathe {
181	  from,
182	  to {
183	    scale: 1;
184	  }
185	  50% {
186	    scale: 1.2;
187	  }
188	}
