221	  position: relative;
222	  display: inline-flex;
223	  align-items: center;
224	  justify-content: center;
225	  padding: fluid(8, 12) fluid(14, 18);
226	  border: 1px solid var(--corner-btn-border);
227	  background: var(--corner-btn-bg);
228	  box-shadow: var(--corner-btn-shadow);
229	  color: var(--corner-btn-color);
230	  font-family: var(--family-ui);
231	  cursor: pointer;
232	  appearance: none;
233	  pointer-events: auto;
234	  transition:
235	    border-color var(--transition-default),
236	    background var(--transition-default),
237	    box-shadow var(--transition-default),
238	    color var(--transition-default);
239	
240	  &__text {
241	    display: inline;
242	  }
243	
244	  &__icon {
245	    display: inline-flex;
246	    align-items: center;
247	    margin-left: fluid(8, 12);
248	    transition: color var(--transition-default);
249	    svg {
250	      width: fluid(14, 16);
251	      height: fluid(14, 16);
252	      fill: currentColor;
253	    }
254	  }
255	
256	  &.no-corner-btn--icon-before &__icon {
257	    margin-left: 0;
258	    margin-right: fluid(8, 12);
259	  }
260	
261	  &.no-corner-btn--icon-only {
262	    padding: 0;
263	  }
264	
265	  &.no-corner-btn--icon-only &__icon {
266	    margin-left: 0;
267	    margin-right: 0;
268	  }
269	
270	  &.no-corner-btn--panel {
271	    --corner-panel-padding: fluid(20, 28);
272	    --corner-panel-border: var(--clr-border-weak);
273	    --corner-panel-background: transparent;
274	    --corner-panel-backdrop-filter: none;
275	    --corner-panel-corner: var(--clr-border-strong);
276	    --corner-panel-border-hover: var(--clr-border-default);
277	    --corner-panel-background-hover: color-mix(
278	      in srgb,
279	      var(--clr-border-weak) 12%,
280	      transparent
281	    );
282	    --corner-panel-hover-offset-y: 0px;
283	    --corner-panel-corner-hover: var(--clr-text-desc);
284	    --corner-btn-border: var(--corner-panel-border);
285	    --corner-btn-bg: var(--corner-panel-background);
286	    --corner-btn-corner: var(--corner-panel-corner);
287	    --corner-btn-hover-border: var(--corner-panel-border-hover);
288	    --corner-btn-hover-bg: var(--corner-panel-background-hover);
289	    --corner-btn-hover-corner: var(--corner-panel-corner-hover);
290	    display: flex;
291	    width: 100%;
292	    min-height: 100%;
293	    align-items: stretch;
294	    justify-content: flex-start;
295	    padding: var(--corner-panel-padding);
296	    cursor: default;
297	    text-align: left;
298	    transition:
299	      border-color var(--transition-default),
300	      background var(--transition-default),
301	      box-shadow var(--transition-default),
302	      color var(--transition-default),
303	      transform var(--transition-default);
304	    backdrop-filter: var(--corner-panel-backdrop-filter);
305	    -webkit-backdrop-filter: var(--corner-panel-backdrop-filter);
306	  }
307	
308	  &--highlight {
309	    --corner-btn-color: var(--clr-text-title);
310	    --corner-btn-border: color-mix(
311	      in srgb,
312	      var(--clr-text-title) 48%,
313	      transparent
314	    );
315	    --corner-btn-bg:
316	      linear-gradient(
317	          180deg,
318	          color-mix(in srgb, var(--clr-text-title) 16%, transparent),
319	          color-mix(in srgb, var(--clr-text-title) 8%, transparent)
320	        )
321	        0 0 / 100% 100% no-repeat,
322	      linear-gradient(
323	        90deg,
324	        transparent 0%,
325	        color-mix(in srgb, var(--clr-text-title) 22%, transparent) 48%,
326	        transparent 100%
327	      )
328	      -140% 0 / 60% 100% no-repeat;
329	    --corner-btn-shadow:
330	      inset 0 1px 0 color-mix(in srgb, var(--clr-text-title) 18%, transparent),
331	      0 0 0 1px color-mix(in srgb, var(--clr-text-title) 12%, transparent),
332	      0 0 fluid(20, 36) color-mix(in srgb, var(--clr-text-title) 22%, transparent);
333	    --corner-btn-corner: color-mix(
334	      in srgb,
335	      var(--clr-text-title) 72%,
336	      var(--clr-border-strong)
337	    );
338	    --corner-btn-hover-border: color-mix(
339	      in srgb,
340	      var(--clr-text-title) 68%,
341	      transparent
342	    );
343	    --corner-btn-hover-bg:
344	      linear-gradient(
345	          180deg,
346	          color-mix(in srgb, var(--clr-text-title) 22%, transparent),
347	          color-mix(in srgb, var(--clr-text-title) 12%, transparent)
348	        )
349	        0 0 / 100% 100% no-repeat,
350	      linear-gradient(
351	        90deg,
352	        transparent 0%,
353	        color-mix(in srgb, var(--clr-text-title) 28%, transparent) 48%,
354	        transparent 100%
355	      )
356	      -140% 0 / 60% 100% no-repeat;
357	    --corner-btn-hover-shadow:
358	      inset 0 1px 0 color-mix(in srgb, var(--clr-text-title) 24%, transparent),
359	      0 0 0 1px color-mix(in srgb, var(--clr-text-title) 18%, transparent),
360	      0 0 fluid(28, 48) color-mix(in srgb, var(--clr-text-title) 32%, transparent);
361	    --corner-btn-hover-corner: var(--clr-text-title);
