402	
403	  &:focus-visible {
404	    color: var(--corner-btn-hover-color);
405	    border-color: var(--corner-btn-hover-border);
406	    background: var(--corner-btn-hover-bg);
407	    box-shadow: var(--corner-btn-hover-shadow);
408	
409	    .no-corner-btn__corner {
410	      color: var(--corner-btn-hover-corner);
411	    }
412	  }
413	
414	  &.no-corner-btn--panel:hover {
