1	@use "sass:map";
2	@use "sass:math";
3	@use "sass:meta";
4	@use "sass:string";
5	
6	@use "./variables" as var;
7	
8	@use "./functions" as func;
9	
10	@use "./headings" as heading;
11	
12	@mixin mq($key-or-size, $direction: "max") {
13	  @if (meta.type-of($key-or-size) == "string") {
14	    $size: map.get(var.$containers, $key-or-size);
15	
16	    @media (#{$direction}-width: #{$size}px) {
17	      @content;
18	    }
19	  } @else if (meta.type-of($key-or-size) == "number") {
20	    @media (#{$direction}-width: #{$key-or-size}px) {
21	      @content;
22	    }
23	  } @else {
24	    @error "No found breakpoint: #{$key-or-size}";
25	  }
26	}
27	
28	@mixin pos-full() {
29	  position: absolute;
30	
31	  top: 0;
32	
33	  left: 0;
34	
35	  width: 100%;
36	
37	  height: 100%;
38	}
39	
40	@mixin pos-center() {
41	  position: absolute;
42	
43	  top: 50%;
44	
45	  left: 50%;
46	
47	  transform: translate(-50%, -50%);
48	
49	  width: 100%;
50	
51	  height: 100%;
52	}
53	
54	@mixin set-fluid($map) {
55	  @each $key, $val in $map {
56	    $min: map.get($val, "min");
57	    $max: map.get($val, "max");
58	
59	    #{$key}: #{func.fluid($min, $max)};
60	  }
61	}
62	
63	@mixin section-fluid-by-map($map) {
64	  $min: map.get($map, "min");
65	
66	  $max: map.get($map, "max");
67	
68	  $max-w: map.get($map, "max-width");
69	
70	  $min-w: map.get($map, "min-width");
71	
72	  padding-bottom: #{func.fluid($min, $max, $min-w, $max-w)};
73	
74	  padding-top: #{func.fluid($min, $max, $min-w, $max-w)};
75	}
